-- ============================================================================
-- InstaCar — Initial schema (PostgreSQL / Supabase)
-- ----------------------------------------------------------------------------
-- Mirrors the canonical MySQL dump: car-rental/if0_42471936_car_rental.sql
-- Table names, column names, enum values, relationships and defaults are kept
-- identical to the legacy app so that every PHP query can be ported 1:1.
--
-- The only structural addition is `users.auth_id`, which links a legacy row
-- to the matching Supabase Auth account. The legacy `users.id` stays the
-- primary key so all legacy foreign keys (bookings.user_id, cars.user_id,
-- bookings.created_by, ...) keep working untouched.
-- ============================================================================

-- ---------------------------------------------------------------------------
-- Enums
-- ---------------------------------------------------------------------------
do $$ begin
  create type public.user_role as enum ('admin', 'operator', 'staff', 'user');
exception when duplicate_object then null; end $$;

do $$ begin
  create type public.booking_status as enum ('Pending', 'Confirmed', 'Released', 'Completed', 'Cancelled');
exception when duplicate_object then null; end $$;

do $$ begin
  create type public.booking_type as enum ('online', 'manual');
exception when duplicate_object then null; end $$;

do $$ begin
  create type public.fulfillment_type as enum ('Pickup', 'Delivery');
exception when duplicate_object then null; end $$;

do $$ begin
  create type public.car_status as enum ('Available', 'Active', 'Maintenance', 'Not Available', 'Reserved');
exception when duplicate_object then null; end $$;

do $$ begin
  create type public.transmission_type as enum ('Manual', 'Automatic');
exception when duplicate_object then null; end $$;

do $$ begin
  create type public.schedule_reason as enum ('Maintenance', 'Personal Use', 'Unavailable', 'Other');
exception when duplicate_object then null; end $$;

do $$ begin
  create type public.review_status as enum ('pending', 'approved', 'rejected', 'replied');
exception when duplicate_object then null; end $$;

