-- ---------------------------------------------------------------------------
-- Helper functions mirroring the PHP session/role helpers
-- ---------------------------------------------------------------------------

-- Returns the legacy `users.id` for the currently signed-in Supabase account.
create or replace function public.current_user_id()
returns bigint
language sql
stable
security definer
set search_path = public
as $$
  select id from public.users where auth_id = auth.uid() limit 1;
$$;

create or replace function public.current_user_role()
returns public.user_role
language sql
stable
security definer
set search_path = public
as $$
  select role from public.users where auth_id = auth.uid() limit 1;
$$;

create or replace function public.current_user_branch_id()
returns bigint
language sql
stable
security definer
set search_path = public
as $$
  select branch_id from public.users where auth_id = auth.uid() limit 1;
$$;

create or replace function public.is_admin()
returns boolean
language sql
stable
security definer
set search_path = public
as $$
  select coalesce(public.current_user_role() = 'admin', false);
$$;

create or replace function public.is_staff()
returns boolean
language sql
stable
security definer
set search_path = public
as $$
  select coalesce(public.current_user_role() = 'staff', false);
$$;

create or replace function public.is_operator()
returns boolean
language sql
stable
security definer
set search_path = public
as $$
  select coalesce(public.current_user_role() = 'operator', false);
$$;

-- Mirrors config/booking_scope_helper.php :: userCanAccessBooking()
--   admin    -> any booking
--   staff    -> bookings whose car belongs to the staff branch
--   operator -> bookings whose car is owned by the operator
--   user     -> own bookings
create or replace function public.user_can_access_booking(p_booking_id bigint)
returns boolean
language sql
stable
security definer
set search_path = public
as $$
  select exists (
    select 1
    from public.bookings b
    join public.cars c on b.car_id = c.id
    where b.id = p_booking_id
      and case public.current_user_role()
        when 'admin'    then true
        when 'staff'    then c.branch_id is not null
                            and c.branch_id = public.current_user_branch_id()
        when 'operator' then c.user_id = public.current_user_id()
        when 'user'     then b.user_id = public.current_user_id()
        else false
      end
  );
$$;

-- Mirrors config/branch_helper.php :: branchScopeSql('branch_id')
-- Admins pass an explicit branch id (or null = all branches).
create or replace function public.branch_scope(p_branch_id bigint)
returns bigint
language sql
stable
security definer
set search_path = public
as $$
  select case
    when public.current_user_role() = 'admin' then p_branch_id
    when public.current_user_role() in ('staff', 'operator') then public.current_user_branch_id()
    else null
  end;
$$;

-- Mirrors the availability overlap rule from METHODOLOGY.md:
--   requested_start <= existing_end AND requested_end >= existing_start
create or replace function public.car_is_available(
  p_car_id bigint,
  p_start_date date,
  p_end_date date,
  p_pickup_time time default null,
  p_return_time time default null,
  p_exclude_booking_id bigint default null
)
returns boolean
language sql
stable
security definer
set search_path = public
as $$
  select
    not exists (
      select 1
      from public.bookings b
      where b.car_id = p_car_id
        and b.status not in ('Cancelled', 'Completed')
        and (p_exclude_booking_id is null or b.id <> p_exclude_booking_id)
        and (
          case
            when p_pickup_time is null or p_return_time is null then
              b.start_date <= p_end_date and b.end_date >= p_start_date
            else
              (b.start_date + b.pickup_time) < (p_end_date + p_return_time)
              and (b.end_date + b.return_time) > (p_start_date + p_pickup_time)
          end
        )
    )
    and not exists (
      select 1
      from public.car_schedules cs
      where cs.car_id = p_car_id
        and cs.start_date <= p_end_date
        and cs.end_date >= p_start_date
    );
$$;

-- ---------------------------------------------------------------------------
-- Row Level Security
-- ---------------------------------------------------------------------------
alter table public.users                 enable row level security;
alter table public.branches              enable row level security;
alter table public.cars                  enable row level security;
alter table public.car_schedules         enable row level security;
alter table public.bookings              enable row level security;
alter table public.booking_payments      enable row level security;
alter table public.booking_photos        enable row level security;
alter table public.booking_remarks       enable row level security;
alter table public.reviews               enable row level security;
alter table public.contact_messages      enable row level security;
alter table public.expenses              enable row level security;
alter table public.site_content          enable row level security;
alter table public.operator_remittances  enable row level security;
alter table public.operator_remittance_photos enable row level security;
alter table public.staff_fee_remittances enable row level security;
alter table public.staff_fee_remittance_photos enable row level security;

-- users ---------------------------------------------------------------------
drop policy if exists users_select_self on public.users;
create policy users_select_self on public.users
  for select using (auth_id = auth.uid() or public.is_admin());

drop policy if exists users_update_self on public.users;
create policy users_update_self on public.users
  for update using (auth_id = auth.uid() or public.is_admin())
  with check (auth_id = auth.uid() or public.is_admin());

drop policy if exists users_insert_admin on public.users;
create policy users_insert_admin on public.users
  for insert with check (public.is_admin());

drop policy if exists users_delete_admin on public.users;
create policy users_delete_admin on public.users
  for delete using (public.is_admin());

-- branches ------------------------------------------------------------------
drop policy if exists branches_read on public.branches;
create policy branches_read on public.branches
  for select using (true);

drop policy if exists branches_write_admin on public.branches;
create policy branches_write_admin on public.branches
  for all using (public.is_admin()) with check (public.is_admin());

-- cars ----------------------------------------------------------------------
drop policy if exists cars_read on public.cars;
create policy cars_read on public.cars
  for select using (true);

drop policy if exists cars_write on public.cars;
create policy cars_write on public.cars
  for all
  using (public.is_admin() or (public.is_operator() and user_id = public.current_user_id()))
  with check (public.is_admin() or (public.is_operator() and user_id = public.current_user_id()));

-- car_schedules -------------------------------------------------------------
drop policy if exists car_schedules_read on public.car_schedules;
create policy car_schedules_read on public.car_schedules
  for select using (true);

drop policy if exists car_schedules_write on public.car_schedules;
create policy car_schedules_write on public.car_schedules
  for all
  using (
    public.is_admin()
    or exists (
      select 1 from public.cars c
      where c.id = car_schedules.car_id
        and c.user_id = public.current_user_id()
    )
  )
  with check (
    public.is_admin()
    or exists (
      select 1 from public.cars c
      where c.id = car_schedules.car_id
        and c.user_id = public.current_user_id()
    )
  );

-- bookings ------------------------------------------------------------------
drop policy if exists bookings_read on public.bookings;
create policy bookings_read on public.bookings
  for select using (
    public.current_user_role() = 'admin'
    or public.user_can_access_booking(id)
  );

drop policy if exists bookings_insert on public.bookings;
create policy bookings_insert on public.bookings
  for insert with check (
    user_id = public.current_user_id()
    or public.current_user_role() in ('admin', 'staff')
  );

drop policy if exists bookings_update on public.bookings;
create policy bookings_update on public.bookings
  for update using (
    public.is_admin()
    or (
      public.is_staff()
      and (
        (branch_id is not null and branch_id = public.current_user_branch_id())
        or exists (
          select 1 from public.cars c
          where c.id = bookings.car_id
            and c.branch_id = public.current_user_branch_id()
        )
      )
    )
  ) with check (
    public.is_admin()
    or (
      public.is_staff()
      and (
        (branch_id is not null and branch_id = public.current_user_branch_id())
        or exists (
          select 1 from public.cars c
          where c.id = bookings.car_id
            and c.branch_id = public.current_user_branch_id()
        )
      )
    )
  );

drop policy if exists bookings_delete on public.bookings;
create policy bookings_delete on public.bookings
  for delete using (public.is_admin());

-- booking_payments ----------------------------------------------------------
drop policy if exists booking_payments_read on public.booking_payments;
