-- --------------------------------------------------------------------------
-- migrations/20260101000400_updated_at_triggers.sql
-- --------------------------------------------------------------------------

-- ============================================================================
-- InstaCar — `ON UPDATE current_timestamp()` triggers
-- ----------------------------------------------------------------------------
-- The legacy MySQL dump declares four timestamp columns with
-- `ON UPDATE current_timestamp()`. Postgres has no column level equivalent, so
-- a trigger keeps the exact same behaviour:
--
--   car_schedules.updated_at
--   reviews.updated_at
--   site_content.updated_at
--   users.created_at          (the legacy dump puts the clause on created_at)
-- ============================================================================

create or replace function public.touch_updated_at()
returns trigger
language plpgsql
as $$
begin
  new.updated_at := now();
  return new;
end;
$$;

drop trigger if exists trg_car_schedules_updated_at on public.car_schedules;
create trigger trg_car_schedules_updated_at
  before update on public.car_schedules
  for each row execute function public.touch_updated_at();

drop trigger if exists trg_reviews_updated_at on public.reviews;
create trigger trg_reviews_updated_at
  before update on public.reviews
  for each row execute function public.touch_updated_at();

drop trigger if exists trg_site_content_updated_at on public.site_content;
create trigger trg_site_content_updated_at
  before update on public.site_content
  for each row execute function public.touch_updated_at();

-- The legacy `users` table carries the `ON UPDATE` clause on `created_at`.
create or replace function public.touch_users_created_at()
returns trigger
language plpgsql
as $$
begin
  new.created_at := now();
  return new;
end;
$$;

drop trigger if exists trg_users_created_at on public.users;
create trigger trg_users_created_at
  before update on public.users
  for each row execute function public.touch_users_created_at();


-- --------------------------------------------------------------------------
-- migrations/20260101000500_public_site_stats.sql
-- --------------------------------------------------------------------------

-- ============================================================================
-- InstaCar — public site statistics
-- ----------------------------------------------------------------------------
-- The legacy `car-rental/index.php` renders four numbers on the landing page
-- (satisfied renters, average rating, review count, available vehicles) plus a
-- "most booked" fleet carousel.
--
-- Those aggregates cross RLS protected tables (`bookings`, `users`, `reviews`),
-- so they are exposed through a single `security definer` function instead of
-- granting anonymous access to the tables themselves.
-- ============================================================================

create or replace function public.public_site_stats()
returns jsonb
language sql
stable
security definer
set search_path = public
as $$
  select jsonb_build_object(
    -- `SELECT COUNT(id) FROM bookings WHERE status IN ('Confirmed','Completed')`
    'confirmed_bookings', (
      select count(*) from public.bookings
       where status in ('Confirmed', 'Completed')
    ),
    -- fallback of the legacy page: `SELECT COUNT(id) FROM users`
    'total_users', (
      select count(*) from public.users
    ),
    -- `SELECT AVG(rating), COUNT(*) FROM reviews`
    'avg_rating', coalesce((
      select avg(rating) from public.reviews
    ), 5.0),
    'total_reviews', (
      select count(*) from public.reviews
    ),
    -- `SELECT COUNT(*) FROM cars`
    'total_cars', (
      select count(*) from public.cars
    ),
    -- the "popular rides" carousel
    'popular_cars', coalesce((
      select jsonb_agg(row_to_json(p))
        from (
          select c.id,
                 c.brand,
                 c.model,
                 c.type,
                 c.fuel_type,
                 c.transmission,
                 c.capacity,
                 c.image_path,
                 c.price_24_hours,
                 c.price_12_hours,
                 c.price_10_hours,
                 c.plate_number,
                 c.status,
                 count(b.id) as total_bookings
            from public.cars c
            left join public.bookings b on c.id = b.car_id
           group by c.id
           order by count(b.id) desc, c.id asc
           limit 6
        ) p
    ), '[]'::jsonb)
  );
$$;

grant execute on function public.public_site_stats()
  to anon, authenticated;


-- --------------------------------------------------------------------------
-- migrations/20260101000600_customer_directory.sql
-- --------------------------------------------------------------------------

-- ============================================================================
-- InstaCar — Customer directory access
-- ----------------------------------------------------------------------------
-- The legacy PHP pages joined `users` inline while listing bookings:
--
--   pages/staff/customers.php   -> every customer (role = 'user') with the
--                                   booking counters of that customer
--   pages/staff/bookings.php     -> the customer name of every booking whose
--                                   car belongs to the staff branch
--   pages/operator/bookings.php  -> the customer name of every booking made
--                                   for a car owned by the operator
--
-- The first `users` policy only allowed a row to be read by its owner or by
-- an admin, which made those pages impossible to reproduce. This migration
-- widens the read policy to exactly the rows the legacy pages exposed.
-- ============================================================================

drop policy if exists users_select_self on public.users;

create policy users_select_self on public.users
  for select using (
    auth_id = auth.uid()
    or public.is_admin()
    -- Staff may list every customer of the platform (legacy staff/customers.php)
    or (public.current_user_role() = 'staff' and public.users.role = 'user')
    -- Staff may read the customer behind a booking of their own branch
    or (
      public.current_user_role() = 'staff'
      and exists (
        select 1
        from public.bookings b
        join public.cars c on c.id = b.car_id
        where b.user_id = public.users.id
          and c.branch_id = public.current_user_branch_id()
      )
    )
    -- Operators may read the customer behind a booking of their own cars
    or (
      public.current_user_role() = 'operator'
      and exists (
        select 1
        from public.bookings b
        join public.cars c on c.id = b.car_id
        where b.user_id = public.users.id
          and c.user_id = public.current_user_id()
      )
    )
  );

-- ---------------------------------------------------------------------------
-- customer_directory()
--
-- Port of the aggregate query of pages/staff/customers.php:
--
--   SELECT u.id, u.name, u.email, u.phone, u.created_at,
--          COUNT(b.id)                                             total_bookings,
--          SUM(b.status = 'Completed')                             completed_bookings,
--          SUM(b.status = 'Cancelled')                              cancelled_bookings,
--          SUM(b.status IN ('Confirmed','Active','Pending'))        active_bookings,
--          (SELECT br.name FROM bookings b2
--             LEFT JOIN branches br ON b2.branch_id = br.id
--            WHERE b2.user_id = u.id ORDER BY b2.id DESC LIMIT 1)    last_branch_name
--   FROM users u LEFT JOIN bookings b ON b.user_id = u.id
--   WHERE u.role = 'user'
--   GROUP BY u.id
--   ORDER BY u.created_at DESC
--
-- NOTE: the legacy query listed 'Active' as a booking status, but the real
-- `booking_status` enum only contains
-- ('Pending','Confirmed','Released','Completed','Cancelled') - in MySQL the
-- unknown value never matched. 'Released' is the status that actually means
-- "the car is currently with the customer", so it is used here.
--
-- Security definer because the aggregate needs to read `bookings` rows that
-- a staff member is not allowed to see individually.
-- ---------------------------------------------------------------------------
create or replace function public.customer_directory()
returns table (
  id                  bigint,
  name                text,
  email               text,
  phone               text,
  created_at          timestamptz,
  total_bookings      bigint,
  completed_bookings  bigint,
  cancelled_bookings  bigint,
  active_bookings     bigint,
  last_branch_name    text
)
language sql
stable
security definer
set search_path = public
as $$
  select
    u.id,
    u.name,
    u.email,
    u.phone,
    u.created_at,
    count(b.id) as total_bookings,
    count(*) filter (where b.status = 'Completed') as completed_bookings,
    count(*) filter (where b.status = 'Cancelled') as cancelled_bookings,
    count(*) filter (where b.status in ('Confirmed', 'Released', 'Pending')) as active_bookings,
    (
      select br.name
      from public.bookings b2
      left join public.branches br on b2.branch_id = br.id
      where b2.user_id = u.id
      order by b2.id desc
      limit 1
    ) as last_branch_name
  from public.users u
  left join public.bookings b on b.user_id = u.id
  where u.role = 'user'
  group by u.id
  order by u.created_at desc;
$$;

revoke all on function public.customer_directory() from public, anon;
grant execute on function public.customer_directory() to authenticated;

-- ---------------------------------------------------------------------------
-- booking_contact(p_booking_id)
--
-- Returns the name, e-mail and phone of the customer behind a booking.
-- The legacy booking tables joined `users` inline; the helper keeps the same
-- information available for callers that may not read the `users` row.
-- ---------------------------------------------------------------------------
create or replace function public.booking_contact(p_booking_id bigint)
returns table (
  id            bigint,
  name          text,
  email         text,
  phone         text,
  guest_name    text
)
language sql
stable
security definer
set search_path = public
as $$
  select
    u.id,
    coalesce(u.name, b.guest_name) as name,
    coalesce(u.email, b.gmail) as email,
    coalesce(u.phone, b.phone_number) as phone,
    b.guest_name
  from public.bookings b
  left join public.users u on u.id = b.user_id
  where b.id = p_booking_id;
$$;

revoke all on function public.booking_contact(bigint) from public, anon;
grant execute on function public.booking_contact(bigint) to authenticated;


-- --------------------------------------------------------------------------
-- migrations/20260101000900_auto_cancel_stale_bookings.sql
-- --------------------------------------------------------------------------

-- ============================================================================
-- InstaCar — auto-cancel stale online Pending bookings
-- ----------------------------------------------------------------------------
-- The legacy online-booking list pages ran this UPDATE on every load:
--
--   pages/admin/bookings_online.php
--   pages/staff/bookings.php          (scoped to the staff branch)
--
--   UPDATE bookings
--      SET status = 'Cancelled', total_price = 500
--    WHERE status = 'Pending'
--      AND booking_type = 'online'
--      AND (end_date < today
--           OR (end_date = today AND return_time < now)
--           OR start_date < today)
--
-- Doing it inside a security-definer function keeps the exact behaviour
-- (including the fixed ₱500 cancellation fee) without granting a page direct
-- write access, and lets the server render a clean list in one round-trip.
--
-- `p_branch_id` = NULL means "every branch" (admin with All Branches).
-- ============================================================================

create or replace function public.auto_cancel_stale_bookings(
  p_branch_id bigint default null
)
returns integer
language plpgsql
security definer
set search_path = public
as $$
declare
  v_count integer;
  v_today date := (now() at time zone 'Asia/Manila')::date;
  v_now   time := (now() at time zone 'Asia/Manila')::time;
begin
  update public.bookings
     set status      = 'Cancelled',
         total_price = 500
   where status       = 'Pending'
     and booking_type = 'online'
     and (p_branch_id is null or branch_id = p_branch_id)
     and (
       end_date < v_today
       or (end_date = v_today and return_time < v_now)
       or start_date < v_today
     );

  get diagnostics v_count = row_count;
  return v_count;
end;
$$;

revoke all on function public.auto_cancel_stale_bookings(bigint) from public;
grant execute on function public.auto_cancel_stale_bookings(bigint)
  to authenticated;


